js='''
const campaigns={all:{name:'All MVA campaigns',plan:5000,channel:'Meta Website + Google Search',landing:'Website + W1 primary page',prepared:'Two channel builds prepared',next:'Verify current creative, routing and campaign settings.'},meta:{name:'Meta · Website',plan:3000,channel:'Meta Website',landing:'Website acquisition',prepared:'Creative and website review package prepared',next:'Review current Meta creative and confirm reporting coverage.'},search:{name:'Google · Search',plan:2000,channel:'Google Search',landing:'W1 primary landing page',prepared:'Search build prepared for review',next:'Verify Search configuration and its W1 destination.'}};
const stages=[{name:'Campaign',status:'Prepared · Held',detail:'The selected campaign is prepared for review. Actual platform delivery, settings and spend are not verified.',next:'Confirm the current creative and configuration before release.'},{name:'Lead received',status:'Live feed unconnected',detail:'A verified lead receipt should connect consent and campaign source. This preview contains no individual lead records.',next:'Connect authorized source receipts without exposing private lead details.'},{name:'AI intake',status:'Execution unverified',detail:'AI intake contact, qualification and transfer are separate stages. An attempted call does not establish a completed transfer.',next:'Verify the work and receiving-team acknowledgement.'},{name:'Firm · Litify',status:'Feedback unconnected',detail:'Firm dispositions should show what happened after transfer. Litify is not connected to this visual preview.',next:'Match authorized firm feedback; leave uncertain matches unresolved.'},{name:'Verified outcome',status:'Not verified',detail:'Signed requires executed-retainer evidence. Converted or sent-retainer stages do not establish a signed case.',next:'Verify the evidence before counting a signed outcome.'},{name:'Optimization',status:'Held for evidence',detail:'Compare trusted campaign spend, intake work and firm outcomes before proposing a change.',next:'Review the exact change with the responsible owner.'}];
let selected='all';let stageIndex=0;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
function update(){const c=campaigns[selected];document.querySelectorAll('[data-scope-name]').forEach(n=>n.textContent=c.name);document.querySelectorAll('[data-channel]').forEach(n=>n.textContent=c.channel);document.querySelectorAll('[data-budget]').forEach(n=>n.textContent=money(c.plan));document.querySelectorAll('[data-landing]').forEach(n=>n.textContent=c.landing);document.querySelectorAll('[data-prepared]').forEach(n=>n.textContent=c.prepared);document.querySelectorAll('[data-next]').forEach(n=>n.textContent=c.next);document.querySelectorAll('[data-campaign]').forEach(n=>n.setAttribute('aria-pressed',String(n.dataset.campaign===selected)));document.querySelectorAll('[data-stage-scope]').forEach(n=>n.textContent='Campaign scope: '+c.name);const selector=document.querySelector('#campaign');if(selector)selector.value=selected;document.querySelector('#filter-status').textContent='Showing '+c.name+' across marketing, AI intake and firm outcomes.';renderStage();}
function renderStage(){const s=stages[stageIndex];document.querySelector('#stage-detail')?.setAttribute('aria-labelledby','stage-'+stageIndex);document.querySelectorAll('[data-stage]').forEach(n=>{n.setAttribute('aria-selected',String(Number(n.dataset.stage)===stageIndex));n.tabIndex=Number(n.dataset.stage)===stageIndex?0:-1;});document.querySelectorAll('[data-stage-title]').forEach(n=>n.textContent=s.name);document.querySelectorAll('[data-stage-status]').forEach(n=>n.textContent=s.status);document.querySelectorAll('[data-stage-description]').forEach(n=>n.textContent=s.detail);document.querySelectorAll('[data-stage-next]').forEach(n=>n.textContent=s.next);document.querySelectorAll('[data-stage-index]').forEach(n=>n.textContent=String(stageIndex+1).padStart(2,'0'));}
document.querySelector('#campaign')?.addEventListener('change',e=>{selected=e.target.value;update();});document.querySelectorAll('[data-campaign]').forEach(n=>n.addEventListener('click',()=>{selected=n.dataset.campaign;update();}));
function activateTab(button,focus=false){const group=button.closest('[role=tablist]');group.querySelectorAll('[role=tab]').forEach(n=>{n.setAttribute('aria-selected',String(n===button));n.tabIndex=n===button?0:-1;});document.querySelectorAll('[data-view]').forEach(n=>n.hidden=n.dataset.view!==button.dataset.tab);document.querySelectorAll('.rail-link').forEach(n=>n.setAttribute('aria-selected',String(n.dataset.tab===button.dataset.tab)));if(focus)button.focus();}
document.querySelectorAll('[role=tab][data-tab]').forEach(n=>n.addEventListener('click',()=>activateTab(n)));document.querySelectorAll('.rail-link').forEach(n=>n.addEventListener('click',()=>activateTab(document.querySelector('[role=tab][data-tab="'+n.dataset.tab+'"]'))));
document.querySelectorAll('[role=tablist]').forEach(group=>group.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;const buttons=[...group.querySelectorAll('[role=tab]')];const i=buttons.indexOf(document.activeElement);if(i<0)return;e.preventDefault();const target=buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1)+buttons.length)%buttons.length];if(target.dataset.stage!==undefined){stageIndex=Number(target.dataset.stage);renderStage();target.focus();}else activateTab(target,true);}));
document.querySelectorAll('[data-stage]').forEach(n=>n.addEventListener('click',()=>{stageIndex=Number(n.dataset.stage);renderStage();}));document.querySelectorAll('[data-evidence]').forEach(n=>n.addEventListener('click',()=>{const d=document.getElementById(n.getAttribute('aria-controls'));d.hidden=!d.hidden;n.setAttribute('aria-expanded',String(!d.hidden));}));update();
'''
def brand():return '<div class="brand"><img alt="Marketing Apes" src="data:image/png;base64,'+logo+'"><div><strong>Client Perspective</strong><small>MARKETING APES · PHILLIPS LAW GROUP</small></div></div>'
def selector():return '<div class="selector"><label for="campaign">Campaign perspective</label><select id="campaign"><option value="all">All MVA campaigns</option><option value="meta">Meta · Website</option><option value="search">Google · Search</option></select></div>'
def metrics():return '<div class="metrics"><article class="metric"><div class="eyebrow">Planned investment</div><div class="value" data-budget>$5,000</div><small>14-day plan · Not live spend</small></article><article class="metric"><div class="eyebrow">Verified leads</div><div class="value unknown">Unconnected</div><small>Current live count unknown</small></article><article class="metric"><div class="eyebrow">Signed outcomes</div><div class="value unknown">Unverified</div><small>Executed-retainer proof required</small></article><article class="metric"><div class="eyebrow">Cost per outcome</div><div class="value unknown">Unavailable</div><small>Needs spend + verified outcomes</small></article></div>'
def scope():return '<div class="scope" data-stage-scope>Campaign scope: All MVA campaigns</div>'
def columns():return '<div class="columns"><article class="panel" data-panel="marketing"><div class="lane-label"><b>01</b><div class="eyebrow">Marketing</div></div><h2 data-channel>Meta Website + Google Search</h2>'+scope()+'<div class="progress-rule"><span></span></div><div class="stage"><strong data-prepared>Two channel builds prepared</strong><span>Preparation status · No live delivery claim</span></div><div class="stage"><strong data-landing>Website + W1 primary page</strong><span>Primary destination for this scope</span></div><div class="stage"><strong>Actual spend unknown</strong><span>Current platform data unconnected</span></div></article><article class="panel" data-panel="intake"><div class="lane-label"><b>02</b><div class="eyebrow">AI intake</div></div><h2>How leads are worked</h2>'+scope()+'<div class="stage"><strong>Receipt → consent</strong><span>Live receipt feed unconnected</span></div><div class="stage"><strong>Contact → qualify</strong><span>AI execution not verified here</span></div><div class="stage"><strong>Transfer → acknowledgement</strong><span>After-hours receiving route pending</span></div></article><article class="panel" data-panel="firm"><div class="lane-label"><b>03</b><div class="eyebrow">Firm · Litify</div></div><h2>What happened next</h2>'+scope()+'<div class="stage"><strong>Firm disposition</strong><span>Litify feedback feed unconnected</span></div><div class="stage"><strong>Executed retainer</strong><span>Signed outcome unverified</span></div><div class="stage"><strong>Learn → improve</strong><span>Optimization held for trusted evidence</span></div></article></div>'
def queue():return '<div class="body-grid"><article class="panel"><div class="panel-head"><div><div class="eyebrow">Next actions</div><h2>What needs a decision</h2>'+scope()+'</div><span class="pill">Held</span></div><div class="activity"><strong data-next>Verify current creative, routing and campaign settings.</strong><p>Review scope must be exact. Current firm approval remains unverified.</p></div><div class="activity"><strong>Confirm the after-hours receiving route</strong><p>Team availability is confirmed; same-line reachability and the saved-lead confirmation still need verification.</p></div><div class="activity"><strong>Assign the responsible reviewers</strong><p>Real assignees and approvers remain blank. No approval or execution controls are available in this visual preview.</p></div></article><article class="panel"><div class="eyebrow">Evidence & freshness</div><h2>Know what the view can prove.</h2><p>The operating plan was observed on October 4, 2026 at 18:17 UTC. This source snapshot does not establish current delivery or performance.</p><button class="copy-button" data-evidence aria-controls="evidence-detail" aria-expanded="false">Show verification rules</button><div class="evidence-detail" id="evidence-detail" hidden>Planning snapshot: version and content hashes verified.<br>Marketing spend: current feed unconnected.<br>AI work: execution unverified.<br>Litify feedback: unconnected.<br>Signed: executed-retainer proof required.<br>Review decisions never start campaigns.</div><div class="lead-empty"><strong>No private lead records shown</strong><p>This demonstration reads no live lead or Litify data.</p></div></article></div>'
def tabs(items):return '<div class="tabs" role="tablist" aria-label="Perspective views">'+''.join('<button id="tab-'+key+'" role="tab" data-tab="'+key+'" aria-controls="view-'+key+'" aria-selected="'+('true' if i==0 else 'false')+'" tabindex="'+('0' if i==0 else '-1')+'">'+label+'</button>' for i,(key,label) in enumerate(items))+'</div>'
def view(key,content,hidden=False):return '<section class="view" role="tabpanel" id="view-'+key+'" aria-labelledby="tab-'+key+'" data-view="'+key+'"'+(' hidden' if hidden else '')+'>'+content+'</section>'
def stage_steps():return '<div class="journey-steps" role="tablist" aria-label="Lead journey stages">'+''.join('<button class="step-button" role="tab" id="stage-'+str(i)+'" aria-controls="stage-detail" data-stage="'+str(i)+'" aria-selected="'+('true' if i==0 else 'false')+'" tabindex="'+('0' if i==0 else '-1')+'"><span class="num">'+str(i+1).zfill(2)+'</span><strong>'+name+'</strong><small>'+status+'</small></button>' for i,(name,status) in enumerate([('Campaign','Prepared · Held'),('Lead received','Feed unconnected'),('AI intake','Execution unverified'),('Firm · Litify','Feedback unconnected'),('Verified outcome','Proof required'),('Optimization','Held for evidence')]))+'</div>'
footer='<footer>Client Perspective · Visual prototype · No live campaign, AI intake or Litify connection.<br>Phillips Arizona MVA · One 14-day plan: $3,000 Meta Website + $2,000 Google Search. No individual lead records or executable actions.</footer>'
heading='<div class="eyebrow">PHILLIPS · ARIZONA MVA</div>'
status='<span class="pill">Prototype · Not live</span>'
filterstatus='<p id="filter-status" class="notice" role="status" aria-live="polite"></p><div class="team-strip"><div class="eyebrow">NEEDS YOUR TEAM</div><strong data-next>Verify current creative, routing and campaign settings.</strong><small>Reviewers not yet assigned · No action is submitted here</small></div>'
# Direction 1: operational scan hierarchy and dark persistent command rail.
signal_overview='<div class="body-grid"><article class="panel"><div class="panel-head"><div><div class="eyebrow">System status</div><h2>The complete lead journey</h2>'+scope()+'</div><span class="pill">Evidence pending</span></div><div class="compact-map">'+''.join('<div class="stage"><strong>'+name+'</strong><span>'+state+'</span></div>' for name,state in [('What marketing brought in','Spend and inquiries unverified'),('What the system did','Contact, qualification and transfer unverified'),('What the firm reported','Litify feedback pending · Signed proof required'),('What happens next','Review exact creative, routing and configuration')])+'</div><div class="lead-empty"><strong>The work is staged. Results need a live source.</strong><p>Missing feedback is a coverage gap, not zero outcomes.</p></div></article><article class="panel"><div class="panel-head"><div><div class="eyebrow">Attention required</div><h2>Needs your team</h2>'+scope()+'</div></div><div class="activity"><strong data-next></strong><p>Exact current creative and configuration still need confirmation.</p></div><div class="activity"><strong>After-hours destination</strong><p>Confirm receiving-line reachability and saved-lead confirmation.</p></div><div class="activity"><strong>Firm outcomes</strong><p>Connect Litify feedback and verify executed retainers.</p></div><div class="notice">Source observation · Oct 4, 18:17 UTC<br>Current live spend, leads and outcomes are unverified.</div></article></div>'
signal='<div class="layout"><aside class="rail">'+brand()+'<div class="eyebrow rail-label">Phillips perspective</div>'+''.join('<button class="rail-link" data-tab="'+k+'" aria-selected="'+('true' if k=='overview' else 'false')+'">'+v+'</button>' for k,v in [('overview','◈  Overview'),('system','↗  Campaign & intake'),('reviews','◎  Reviews & evidence')])+'<div class="rail-foot">ONE CONNECTED PICTURE<br>Marketing → AI → Firm<br><br>Prototype · No live changes</div></aside><main class="main"><div class="mobile-brand">'+brand()+'</div><div class="topline"><div class="eyebrow"><span class="signal-dot"></span>YOUR SYSTEM, AT A GLANCE</div>'+status+'</div><div class="page-title"><div>'+heading+'<h1>Clarity across<br>every moving part.</h1><p>Campaigns. AI intake. Firm outcomes. Know what is ready, what is happening and what still needs proof.</p></div>'+selector()+'</div>'+filterstatus+metrics()+tabs([('overview','Overview'),('system','Campaign & intake'),('reviews','Reviews & evidence')])+view('overview',signal_overview)+view('system',columns(),True)+view('reviews',queue(),True)+footer+'</main></div>'
# Direction 2: process-first editorial journey with interactive stage inspection.
flow_detail='<div class="detail-stage" id="stage-detail" role="tabpanel" aria-label="Selected journey stage"><div><span class="detail-index" data-stage-index>01</span><div class="eyebrow" style="margin-top:15px">SELECTED STAGE</div><h2 data-stage-title>Campaign</h2><span class="pill" data-stage-status>Prepared · Held</span></div><div class="flow-detail-right">'+scope()+'<h3 style="margin-top:20px">What this stage tells you</h3><p data-stage-description></p><h3>What moves it forward</h3><p data-stage-next></p><div class="lead-empty"><strong>No individual leads are connected</strong><p>The diagram explains the workflow; it does not show fabricated lead activity.</p></div></div></div>'
flow='<main class="main"><header class="topline flow-top">'+brand()+status+'</header><div class="page-title"><div>'+heading+'<h1>Follow the work.<br><em>Understand the outcome.</em></h1><p>One journey, from the first click through AI intake to your firm’s feedback. Every step tells you what we know—and what comes next.</p></div>'+selector()+'</div>'+filterstatus+tabs([('journey','The journey'),('system','Campaign breakdown'),('reviews','Review queue')])+view('journey',stage_steps()+flow_detail+metrics())+view('system',columns()+metrics(),True)+view('reviews',queue(),True)+footer+'</main>'
# Direction 3: campaign-led workspace; actual campaign choices coordinate work lanes.
picks='<div class="campaign-picks">'+''.join('<button data-campaign="'+key+'" aria-pressed="'+('true' if key=='all' else 'false')+'"><strong>'+name+'</strong><small>'+cost+'</small><div class="mini-rule"></div></button>' for key,name,cost in [('all','All MVA','$5,000 / 14 days'),('meta','Meta Website','$3,000 planned'),('search','Google Search','$2,000 planned')])+'</div>'
workspace='<main class="main"><header class="topline workspace-top">'+brand()+status+'</header><div class="workspace-shell"><aside class="campaign-sidebar"><div class="eyebrow">CAMPAIGN SELECTOR</div><h2>Choose your<br>perspective.</h2>'+picks+'<p class="sidebar-note">The campaign selection follows you across marketing, AI intake and Litify outcomes. All amounts are planned, not verified spend.</p></aside><div class="workspace-content"><div class="page-title"><div>'+heading+'<h1>Your campaign.<br>The whole workspace.</h1><p>Bring the plan, intake work and your firm’s outcomes into the same view.</p></div></div><div class="selected-summary"><div><div class="eyebrow">CURRENT CAMPAIGN SCOPE</div><strong data-scope-name>All MVA campaigns</strong><p data-landing>Website + W1 primary page</p></div></div>'+filterstatus+tabs([('workspace','Workspace'),('results','Results'),('reviews','Next actions')])+view('workspace',columns())+view('results',metrics()+'<article class="panel"><h2>The outcome must be evidenced.</h2>'+scope()+'<p>Campaign spend and executed-retainer outcomes must cover a comparable period. No live performance is connected to this prototype.</p><div class="line-item"><strong>Firm feedback</strong><span>Litify feed unconnected</span></div><div class="line-item"><strong>Signed</strong><span>Executed-retainer evidence required</span></div><div class="line-item"><strong>Optimization</strong><span>Held for trusted evidence</span></div></article>',True)+view('reviews',queue(),True)+footer+'</div></div></main>'
# Shared LFMA family: ink typography, light lilac canvas and restrained cyan/violet accents.
family=""" .team-strip{display:grid;grid-template-columns:160px 1fr;gap:7px 12px;padding:14px 18px;border:1px solid #dcd7f1;border-radius:12px;background:#eeeafa;margin:12px 0 22px}.team-strip .eyebrow{align-self:center;color:#65509b}.team-strip strong{font-size:12px;line-height:1.5}.team-strip small{grid-column:2;font-size:10px;color:#6c6681}@media(max-width:650px){.team-strip{grid-template-columns:1fr;padding:14px}.team-strip small{grid-column:1}.team-strip strong{font-size:12px}} :root{--bg:#f4f6ff;--surface:#ffffff;--ink:#0d1026;--muted:#5a5f7d;--line:#e0e3f0;--accent:#7051da;--focus:#7051da;--tint:#eeebfb}body{background:radial-gradient(ellipse at 90% 0,rgba(0,200,255,.06),transparent 50%),var(--bg)}.brand img{border-radius:50%;border:1px solid #d7daeb}.pill{background:#ffffff80}.metric{box-shadow:0 5px 18px #0d102604}.progress-rule span{background:linear-gradient(90deg,#00a4d6,#7b5cff)}"""
styles['01-signal']+=family+""".rail{background:#14192e;color:#fff;border:0}.rail .brand small,.rail-label,.rail-foot{color:#aeb8d2}.rail-link{color:#aeb8d2}.rail-link[aria-selected=true]{background:#26344b;color:#b5eaff}.metric:first-child{background:linear-gradient(135deg,#f0ecff,#eafaff);border-color:#d9d4f2}.signal-dot{background:#7051da}.panel-head .eyebrow,.section-link{color:#7051da}.main{max-width:1350px}.rail .brand strong{color:#fff}"""
styles['02-flow']+=family+""".page-title h1 em{color:#7051da}.step-button[aria-selected=true]{background:#edeafb}.detail-stage .detail-index,.detail-stage .eyebrow{color:#7051da}.flow-top{border-color:#e0e3f0}.detail-stage{border-radius:16px}.panel{border-radius:14px}.columns .panel{border-top-color:#a38aed}.metrics .metric{box-shadow:none}"""
styles['03-workspace']+=family+""".campaign-sidebar{background:#191e35}.campaign-sidebar .eyebrow,.sidebar-note{color:#b4bdd9}.campaign-picks button{background:#242b46;border-color:#414c6a;color:#eef1ff}.campaign-picks small{color:#b7c2e0}.campaign-picks button[aria-pressed=true]{background:#e4ddff;color:#281957;border-color:#b5a0f1}.campaign-picks button[aria-pressed=true] small{color:#564083}.stage{background:#f7f8fd}.tabs button[aria-selected=true]{background:#14192e}.workspace-inline-notice{color:#5a5f7d}"""
for key,content in [('01-signal',signal),('02-flow',flow),('03-workspace',workspace)]:
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Client Perspective · '+key.split('-')[1].title()+' direction</title><style>'+base_css+styles[key]+'</style></head><body>'+content+'<script>'+js+'</script></body></html>'
 (out/(key+'.html')).write_text(html)
 print(out/(key+'.html'))
